"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { CircleHelp, Minus, Plus } from "./icons";

// Number Input: generated by UIX from the design system. Same variants and sizes as the Figma component.

const numberInputVariants = cva(
  "flex w-full items-center overflow-hidden transition-colors border border-line-default bg-surface hover:border-line-strong focus-within:ring-3 focus-within:ring-line-focus focus-within:border-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-disabled [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-icon-secondary rounded-md",
  {
    variants: {
      size: {
        sm: "h-8 [&>[data-area]]:px-3 [&>button]:size-[30px]",
        md: "h-10 [&>[data-area]]:px-3 [&>button]:size-[38px]",
        lg: "h-12 [&>[data-area]]:px-4 [&>button]:size-[46px]",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface NumberInputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size" | "prefix" | "type" | "value" | "defaultValue" | "onChange">,
    VariantProps<typeof numberInputVariants> {
  label?: React.ReactNode;
  /** Right-aligned note next to the label, for example "Optional". */
  secondaryLabel?: React.ReactNode;
  /** Message under the field. */
  feedback?: React.ReactNode;
  /** Same as feedback. */
  helper?: React.ReactNode;
  /** Error message; also marks the field invalid and replaces the feedback. */
  error?: string;
  /** Current value (controlled). */
  value?: number;
  defaultValue?: number;
  /** Called with the new number; the field clamps it to min / max when it loses focus. */
  onValueChange?: (value: number) => void;
  /** Avatar at the start (for example <Avatar size="xs" initials="AB" />). */
  leadingAvatar?: React.ReactNode;
  /** Icon at the start. */
  leadingIcon?: React.ReactNode;
  /** Selector or text at the start, for example "Email ▾". */
  leadingContent?: React.ReactNode;
  /** Hairline after the leading parts. */
  leadingDivider?: boolean;
  /** Fixed text before the value, for example "https://". */
  prefix?: React.ReactNode;
  /** Tag chips before the value. */
  tags?: React.ReactNode[];
  /** Fixed text after the value, for example ".com". */
  suffix?: React.ReactNode;
  /** Hairline before the trailing parts. */
  trailingDivider?: boolean;
  /** Action at the end, for example a "Copy" button. */
  trailingContent?: React.ReactNode;
  /** Help icon; a string becomes its accessible name and tooltip. */
  helpIcon?: boolean | string;
  /** Icon at the end. */
  trailingIcon?: React.ReactNode;
}

const NumberInput = React.forwardRef<HTMLInputElement, NumberInputProps>(
  ({ className, size, label, secondaryLabel, feedback, helper, error, required, id, disabled, leadingAvatar, leadingIcon, leadingContent, leadingDivider, prefix, tags, suffix, trailingDivider, trailingContent, helpIcon, trailingIcon, value, defaultValue, onValueChange, min, max, step = 1, ...props }, ref) => {
    const autoId = React.useId();
    const fieldId = id ?? autoId;
    const hintId = fieldId + "-hint";
    const message = error || feedback || helper;
    const hint = message ? { "aria-describedby": hintId } : {};
    const [inner, setInner] = React.useState<number | "">(defaultValue ?? "");
    const current = value ?? inner;
    const lo = min != null ? Number(min) : -Infinity;
    const hi = max != null ? Number(max) : Infinity;
    const commit = (next: number | "") => {
      const clamped = next === "" ? "" : Math.min(hi, Math.max(lo, next));
      setInner(clamped);
      if (clamped !== "") onValueChange?.(clamped);
    };
    const bump = (direction: number) => commit(Math.round(((current === "" ? 0 : current) + direction * Number(step)) * 1e6) / 1e6);
    return (
      <div data-slot="number-input" data-kind="field" className={cn("skin-quiet flex w-full flex-col gap-1-5", className)}>
        {label ? (
          <div className="flex items-baseline justify-between gap-2">
            <label htmlFor={fieldId} className={cn("text-label-medium text-fg-primary", disabled && "text-fg-disabled")}>
              {label}
              {required ? <span aria-hidden className="ml-0.5 text-fg-danger">*</span> : null}
            </label>
            {secondaryLabel ? <span className="text-body-small text-fg-tertiary">{secondaryLabel}</span> : null}
          </div>
        ) : null}
        <div data-kind="field" className={cn(numberInputVariants({ size }), error && "border-line-danger hover:border-line-danger focus-within:border-line-danger focus-within:ring-line-danger")}>
          <div data-area="" className="flex min-w-0 flex-1 items-center gap-2">
            {leadingAvatar}
            {leadingIcon}
            {leadingContent ? <span className="shrink-0 text-body-medium text-fg-secondary">{leadingContent}</span> : null}
            {leadingDivider ? <span aria-hidden className="h-5 w-px shrink-0 bg-line-default" /> : null}
            {prefix ? <span className="shrink-0 text-body-medium text-fg-secondary">{prefix}</span> : null}
            {tags?.map((tag, index) => (
              <span key={index} className="inline-flex shrink-0 items-center rounded-full bg-subtle text-fg-primary text-label-small px-2 py-0-5">
                {tag}
              </span>
            ))}
            <input ref={ref} id={fieldId} type="number" min={min} max={max} step={step} disabled={disabled} required={required} aria-invalid={!!error} {...hint} {...props} value={current} onChange={(event) => commit(event.target.value === "" ? "" : Number(event.target.value))} onBlur={() => current !== "" && commit(current)} className="min-w-0 flex-1 bg-transparent outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none text-body-medium text-fg-primary placeholder:text-fg-tertiary disabled:text-fg-disabled disabled:cursor-not-allowed" />
            {suffix ? <span className="shrink-0 text-body-medium text-fg-secondary">{suffix}</span> : null}
            {trailingDivider ? <span aria-hidden className="h-5 w-px shrink-0 bg-line-default" /> : null}
            {trailingContent ? <span className="shrink-0 cursor-pointer text-label-medium text-fg-brand">{trailingContent}</span> : null}
            {helpIcon ? (
              <span role="img" aria-label={typeof helpIcon === "string" ? helpIcon : "Help"} title={typeof helpIcon === "string" ? helpIcon : void 0} className="inline-flex shrink-0 text-icon-secondary">
                <CircleHelp aria-hidden />
              </span>
            ) : null}
            {trailingIcon}
          </div>
          <span aria-hidden className="w-px self-stretch bg-line-subtle" />
          <button type="button" aria-label="Decrease" disabled={disabled || (current !== "" && current <= lo)} onClick={() => bump(-1)} className="inline-flex shrink-0 cursor-pointer items-center justify-center transition-colors text-icon-secondary hover:bg-subtle hover:text-icon-primary focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:pointer-events-none disabled:text-fg-disabled">
            <Minus aria-hidden />
          </button>
          <span aria-hidden className="w-px self-stretch bg-line-subtle" />
          <button type="button" aria-label="Increase" disabled={disabled || (current !== "" && current >= hi)} onClick={() => bump(1)} className="inline-flex shrink-0 cursor-pointer items-center justify-center transition-colors text-icon-secondary hover:bg-subtle hover:text-icon-primary focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:pointer-events-none disabled:text-fg-disabled">
            <Plus aria-hidden />
          </button>
        </div>
        {message ? (
          <p id={hintId} className={cn("text-body-small text-fg-secondary", error && "text-fg-danger")}>
            {message}
          </p>
        ) : null}
      </div>
    );
  },
);
NumberInput.displayName = "NumberInput";

export { NumberInput, numberInputVariants };
